###########################################################
# All-electrode posterior probability after SESOI correction
#
# Reads the cell-level output generated by 13_compute_delta_sesoi.R and plots
# P(Delta > electrode-specific SESOI) for all electrodes.
###########################################################

library(dplyr)
library(tidyr)
library(readr)
library(ggplot2)

source(file.path(Sys.getenv("PROJECT_ROOT", unset = getwd()), "code/utils.R"))

inputs <- slide_inputs()
diag_subdir <- Sys.getenv("DIAG_OUT_SUBDIR", "high_heterogeneity_seed001_sesoi")
tag <- Sys.getenv("DIAG_TAG", "high_heterogeneity_seed001")
baseline_end <- as.numeric(Sys.getenv("SESOI_BASELINE_END", "0.10"))
odds_threshold <- as.numeric(Sys.getenv("ODDS_THRESHOLD", "10"))
threshold_type_requested <- Sys.getenv(
    "SESOI_THRESHOLD_TYPE", "electrode_delta_sesoi"
)
stopifnot(threshold_type_requested %in%
              c("global_delta_sesoi", "electrode_delta_sesoi"))

diag_dir <- file.path(project_root(), "results", "diagnostics", diag_subdir)
fig_dir <- file.path(project_root(), "results", "figures", diag_subdir)
dir.create(fig_dir, recursive = TRUE, showWarnings = FALSE)

cells_file <- file.path(
    diag_dir, paste0("delta_sesoi_posterior_cells_", tag, ".csv")
)
threshold_file <- file.path(
    diag_dir, paste0("delta_sesoi_thresholds_", tag, ".csv")
)
stopifnot(file.exists(cells_file), file.exists(threshold_file))

posterior_cells <- read_csv(cells_file, show_col_types = FALSE) %>%
    filter(abs(baseline_end - .env$baseline_end) < 1e-10,
           threshold_type == .env$threshold_type_requested)
thresholds <- read_csv(threshold_file, show_col_types = FALSE) %>%
    filter(abs(baseline_end - .env$baseline_end) < 1e-10,
           threshold_type == .env$threshold_type_requested) %>%
    select(channel, sesoi)

gt <- readRDS(inputs$gt_file)
truth_cells <- continuous_truth_cells(gt) %>%
    rename(true_effect = effect) %>%
    left_join(thresholds, by = "channel") %>%
    mutate(truth_active = true_effect > sesoi)

make_bands <- function(data, active_col) {
    data %>%
        arrange(channel, time) %>%
        group_by(channel) %>%
        mutate(active = .data[[active_col]],
               run = cumsum(c(TRUE, diff(active) != 0))) %>%
        filter(active) %>%
        group_by(channel, run) %>%
        summarise(xmin = min(time), xmax = max(time), .groups = "drop")
}

detected_bands <- make_bands(posterior_cells, "flagged")
truth_bands <- make_bands(truth_cells, "truth_active")

channel_order <- posterior_cells %>%
    distinct(channel, distance_to_seed) %>%
    arrange(distance_to_seed, channel) %>%
    pull(channel)

posterior_cells <- posterior_cells %>%
    mutate(channel = factor(channel, levels = channel_order))
detected_bands <- detected_bands %>%
    mutate(channel = factor(channel, levels = channel_order))
truth_bands <- truth_bands %>%
    mutate(channel = factor(channel, levels = channel_order))

p_threshold <- odds_threshold / (odds_threshold + 1)
threshold_summary <- thresholds %>%
    summarise(minimum = min(sesoi), median = median(sesoi), maximum = max(sesoi))
threshold_label <- if (threshold_type_requested == "global_delta_sesoi") {
    "global SESOI"
} else {
    "electrode-specific SESOI"
}
threshold_file_label <- if (threshold_type_requested == "global_delta_sesoi") {
    "global_sesoi"
} else {
    "electrode_sesoi"
}
probability_axis <- if (threshold_type_requested == "global_delta_sesoi") {
    expression(Pr(Delta > delta[global] ~ "|" ~ data))
} else {
    expression(Pr(Delta > delta[c] ~ "|" ~ data))
}

p <- ggplot(posterior_cells, aes(time, p_sig)) +
    geom_rect(
        data = truth_bands,
        aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf),
        fill = "#377EB8", alpha = 0.10, inherit.aes = FALSE
    ) +
    geom_rect(
        data = detected_bands,
        aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf),
        fill = "#1EC27D", alpha = 0.20, inherit.aes = FALSE
    ) +
    geom_hline(yintercept = p_threshold, colour = "darkgreen",
               linetype = "dashed", linewidth = 0.28) +
    geom_line(colour = "black", linewidth = 0.38) +
    facet_wrap(~ channel, ncol = 7) +
    coord_cartesian(ylim = c(0, 1)) +
    labs(
        title = paste("All-electrode posterior probability with", threshold_label),
        subtitle = sprintf(
            paste0("High heterogeneity, seed 1; %s from 0-%.2f s baseline; ",
                   "SESOI min/median/max = %.3f / %.3f / %.3f uV"),
            threshold_label, baseline_end, threshold_summary$minimum,
            threshold_summary$median, threshold_summary$maximum
        ),
        caption = paste0(
            "Blue background: true effect > electrode SESOI; green background: posterior odds > ",
            odds_threshold, "; dashed horizontal: P = ", round(p_threshold, 3),
            ". Electrodes are ordered by distance from CZ."
        ),
        x = "Time (s)",
        y = probability_axis
    ) +
    theme_minimal(base_size = 8) +
    theme(
        strip.text = element_text(face = "bold", size = 7),
        axis.text = element_text(size = 6),
        panel.grid.minor = element_blank(),
        plot.title = element_text(face = "bold", size = 13),
        plot.subtitle = element_text(size = 8.5),
        plot.caption = element_text(size = 7, hjust = 0)
    )

out_file <- file.path(
    fig_dir,
    paste0("posterior_p_sig_facets_", tag,
           "_all61_", threshold_file_label, ".pdf")
)
ggsave(out_file, p, width = 11.5, height = 14.5, device = cairo_pdf)
message("Wrote: ", out_file)
